public sealed class DatabaseSchemaV36Initializer(MKSANContext db) {
 public const string Sql="""
ALTER TABLE "Salas" ADD COLUMN IF NOT EXISTS "Localizacao" varchar(120) NOT NULL DEFAULT '';
