CREATE TABLE IF NOT EXISTS "SessoesTele" (
 "Id" uuid PRIMARY KEY, "ConsultaId" integer NOT NULL REFERENCES "Consultas"("Id") ON DELETE CASCADE,
 "UsuarioId" varchar(450) NOT NULL, "Papel" varchar(20) NOT NULL, "Snapshot" varchar(180) NOT NULL,
 "Estado" varchar(20) NOT NULL, "EntradaEm" timestamp with time zone NOT NULL,
 "UltimoSinalEm" timestamp with time zone NOT NULL, "ConectadaEm" timestamp with time zone NULL,
 "SaidaEm" timestamp with time zone NULL, "MotivoSaida" varchar(80) NULL
);
CREATE INDEX IF NOT EXISTS "IX_SessoesTele_ConsultaId_EntradaEm" ON "SessoesTele" ("ConsultaId","EntradaEm");
CREATE INDEX IF NOT EXISTS "IX_SessoesTele_UsuarioId_UltimoSinalEm" ON "SessoesTele" ("UsuarioId","UltimoSinalEm");
""";
 public Task AplicarAsync(CancellationToken ct=default)=>db.Database.ExecuteSqlRawAsync(Sql,ct);
